<div style="overflow:auto"><table><thead><tr><th>Item</th><th>Price</th><th>Qty</th><th>Total</th><th></th></tr></thead><tbody id="cart"></tbody></table></div>
<p class="total">Subtotal: PKR <span id="subtotal">0.00</span></p><label>Discount (PKR)</label><input type="number" min="0" step=".01" name="discount_amount" id="discount" value="0" oninput="calculate()"><label>Tax (PKR)</label><input type="number" min="0" step=".01" name="tax_amount" id="tax" value="0" oninput="calculate()"><p class="total">Total: PKR <span id="total">0.00</span></p><label>Payment Method</label><select name="payment_method"><option value="cash">Cash</option><option value="card">Card</option><option value="bank_transfer">Bank transfer</option><option value="mobile_wallet">Mobile wallet</option><option value="other">Other</option></select><label>Payment Reference (optional)</label><input name="payment_reference" placeholder="Transaction / reference number"><label>Amount Received (PKR)</label><input type="number" min="0" step=".01" name="amount_paid" id="paid" required oninput="calculateChange()"><p>Change: PKR <strong id="change">0.00</strong></p><input name="notes" placeholder="Sale notes"><div id="hiddenItems"></div><button type="submit" onclick="return validateSale()">Complete Sale & Print Receipt</button><p id="error" style="color:#b42318"></p></form></section></div></main>
<script>
let cart=[];
function money(n){return Number(n||0).toFixed(2)}
function branch(){return document.getElementById('branch').value}
async function searchProducts(){const q=document.getElementById('search').value.trim();if(!q)return; if(!branch()){alert('Select a branch first.');return}document.getElementById('formBranch').value=branch();const url='{{ route('pos.search') }}?q='+encodeURIComponent(q)+'&branch_id='+encodeURIComponent(branch());const r=await fetch(url,{headers:{'Accept':'application/json'}});if(!r.ok){document.getElementById('results').textContent='Search failed. Check branch access.';return}const data=await r.json();const box=document.getElementById('results');box.innerHTML='';if(!data.length){box.textContent='No matching active products found.';return}data.forEach(v=>{const b=document.createElement('button');b.type='button';b.disabled=v.stock<1;b.textContent=v.name+' | '+v.size+' / '+v.color+' | '+v.sku+' | PKR '+money(v.price)+' | Stock '+v.stock;b.onclick=()=>add(v);box.appendChild(b)})}
function add(v){const found=cart.find(x=>x.id===v.id);if(found){if(found.qty>=v.stock){alert('Not enough stock.');return}found.qty++}else cart.push({...v,qty:1});render()}
function removeItem(id){cart=cart.filter(x=>x.id!==id);render()}
function setQty(id,value){const item=cart.find(x=>x.id===id);if(!item)return;const qty=Math.max(1,Math.min(Number(value)||1,item.stock));item.qty=qty;render()}
function render(){const body=document.getElementById('cart');body.innerHTML='';cart.forEach(v=>{const tr=document.createElement('tr');tr.innerHTML='<td>'+v.name+'<br><small>'+v.size+' / '+v.color+' · '+v.sku+'</small></td><td>'+money(v.price)+'</td><td><input style="width:65px" type="number" min="1" max="'+v.stock+'" value="'+v.qty+'" onchange="setQty('+v.id+',this.value)"></td><td>'+money(v.price*v.qty)+'</td><td><button type="button" class="secondary" onclick="removeItem('+v.id+')">×</button></td>';body.appendChild(tr)});document.getElementById('hiddenItems').innerHTML=cart.map((v,i)=>'<input type="hidden" name="items['+i+'][product_variant_id]" value="'+v.id+'"><input type="hidden" name="items['+i+'][quantity]" value="'+v.qty+'">').join('');calculate()}
function calculate(){const sub=cart.reduce((s,v)=>s+v.price*v.qty,0);const disc=Number(document.getElementById('discount').value||0);const tax=Number(document.getElementById('tax').value||0);document.getElementById('subtotal').textContent=money(sub);document.getElementById('total').textContent=money(Math.max(0,sub-disc+tax));if(!document.getElementById('paid').value)document.getElementById('paid').value=money(Math.max(0,sub-disc+tax));calculateChange()}
function calculateChange(){const total=Number(document.getElementById('total').textContent||0);const paid=Number(document.getElementById('paid').value||0);document.getElementById('change').textContent=money(Math.max(0,paid-total))}
function validateSale(){document.getElementById('error').textContent='';if(!branch()){document.getElementById('error').textContent='Select a branch.';return false}document.getElementById('formBranch').value=branch();if(!cart.length){document.getElementById('error').textContent='Add at least one item.';return false}const total=Number(document.getElementById('total').textContent);if(Number(document.getElementById('paid').value)<total){document.getElementById('error').textContent='Amount received is less than the total.';return false}return true}
document.getElementById('search').addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();searchProducts()}});if(branch())document.getElementById('formBranch').value=branch();
</script></body></html>